#include <sys/timerfd.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <stdint.h>
#include <errno.h>

#define ERR_EXIT(msg) do { perror(msg); exit(EXIT_FAILURE); } while (0)

int main() {
    int tfd;
    struct itimerspec ts;
    uint64_t expirations;

    // 1. Create a CLOCK_MONOTONIC timer file descriptor
    tfd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (tfd == -1)
        ERR_EXIT("timerfd_create");

    // 2. Define the timer settings: 500ms initial delay, 500ms interval.
    ts.it_value.tv_sec = 0;
    ts.it_value.tv_nsec = 500000000; // 0.5 seconds
    ts.it_interval.tv_sec = 0;
    ts.it_interval.tv_nsec = 500000000;

    // 3. Arm the timer using relative time (flags=0)
    if (timerfd_settime(tfd, 0, &ts, NULL) == -1)
        ERR_EXIT("timerfd_settime");

    printf("Timer armed for 500ms periodicity. Reading 5 times.\n");

    // 4. Wait for 5 expirations (read blocks until expiration occurs)
    for (int i = 0; i < 5; i++) {
        ssize_t s = read(tfd, &expirations, sizeof(expirations));

        if (s == -1) ERR_EXIT("read");
        if (s != sizeof(expirations)) {
             fprintf(stderr, "Short read\n");
             exit(EXIT_FAILURE);
        }

        printf("[%d] Timer fired. Expiration count accumulated since last read: %lu\n", 
               i + 1, (unsigned long)expirations);
    }

    // Disarm the timer by setting new_value.it_value to zero
    ts.it_value.tv_sec = 0;
    ts.it_value.tv_nsec = 0;
    ts.it_interval.tv_sec = 0;
    ts.it_interval.tv_nsec = 0;
    timerfd_settime(tfd, 0, &ts, NULL);

    close(tfd);
    return EXIT_SUCCESS;
}
